package tw.com.tft.documentscanner.export;import android.app.*;import android.content.*;import android.net.*;import androidx.core.content.FileProvider;import java.io.*;import java.util.*;public final class ShareManager{public static ArrayList<Uri> filesToUris(Activity a,List<File>f){ArrayList<Uri>u=new ArrayList<>();for(File x:f)u.add(FileProvider.getUriForFile(a,a.getPackageName()+".files",x));return u;}public static void share(Activity a,ArrayList<Uri>u){if(u.isEmpty())return;Intent i;if(u.size()==1){i=new Intent(Intent.ACTION_SEND);i.putExtra(Intent.EXTRA_STREAM,u.get(0));}else{i=new Intent(Intent.ACTION_SEND_MULTIPLE);i.putParcelableArrayListExtra(Intent.EXTRA_STREAM,u);}i.setType("image/jpeg");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);Intent l=new Intent(i);l.setPackage("jp.naver.line.android");try{a.startActivity(l);}catch(ActivityNotFoundException e){a.startActivity(Intent.createChooser(i,"分享掃描文件"));}}}